mapper.select:
SELECT m.trade_date as tradeDate, m.money_direction_factor as money, c.credit_direction_factor as credit, c.growth_direction_factor as growth FROM stock_risk_budget_money_factors m JOIN stock_risk_budget_credit_growth_factors c ON SUBSTRING(m.trade_date, 1, 7) = c.data_month
AND m.trade_date >= #{startDate}
AND m.trade_date <= #{endDate}
ORDER BY m.trade_date ASC

SELECT s.trade_date as tradeDate, COALESCE(m.money_direction_factor, CASE s.stage WHEN 1 THEN 1.0 WHEN 2 THEN 1.0 WHEN 3 THEN -1.0 WHEN 4 THEN -1.0 WHEN 5 THEN -1.0 WHEN 6 THEN 1.0 ELSE 0.0 END ) as money, COALESCE(c.credit_direction_factor, CASE s.stage WHEN 1 THEN 1 WHEN 2 THEN 1 WHEN 3 THEN 1 WHEN 4 THEN -1 WHEN 5 THEN -1 WHEN 6 THEN -1 ELSE 0 END ) as credit, COALESCE(c.growth_direction_factor, CASE s.stage WHEN 1 THEN -1 WHEN 2 THEN 1 WHEN 3 THEN 1 WHEN 4 THEN 1 WHEN 5 THEN -1 WHEN 6 THEN -1 ELSE 0 END ) as growth, s.stage as stage FROM stock_historical_stage s LEFT JOIN stock_risk_budget_money_factors m ON s.trade_date = m.trade_date LEFT JOIN stock_risk_budget_credit_growth_factors c ON SUBSTRING(s.trade_date, 1, 7) = c.data_month
AND s.trade_date >= #{startDate}
AND s.trade_date <= #{endDate}
ORDER BY s.trade_date ASC
